/*
 * A257905  Sequence (a(n)) generated by Rule 3 (in Comments) with a(1) = 0
 *          and d(1) = 0.
 * https://oeis.org/A257905
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 5, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A257905 – Rule 3 (with a(1)=0, d(1)=0)
   Implemented by direct simulation of the definition.  */
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/*-- static state -------------------------------------------------------*/
static seq_t *seq_arr       = NULL;
static size_t seq_cap       = 0;
static size_t seq_len       = 0;              /* number of terms stored   */

static bool  *a_used       = NULL;            /* a(k) values seen        */
static size_t a_used_cap    = 0;

static bool  *d_pos_used    = NULL;            /* d(k) >= 0 values seen   */
static size_t d_pos_cap     = 0;
static bool  *d_neg_used    = NULL;            /* d(k) < 0   values seen   */
static size_t d_neg_cap     = 0;

static size_t computed_n = 0; /* last index that has been generated (1‑based) */

/*-- helpers to grow boolean arrays -------------------------------------*/
static void ensure_a_cap(size_t idx)
{
    if (idx < a_used_cap) return;
    size_t new_cap = a_used_cap? a_used_cap * 2 : 1024;
    if (new_cap <= idx) new_cap = idx + 1;
    bool *new_arr = (bool *)malloc(new_cap);
    memset(new_arr, 0, new_cap);
    if (a_used) {
        memcpy(new_arr, a_used, a_used_cap);
        free(a_used);
    }
    a_used      = new_arr;
    a_used_cap  = new_cap;
}
static void ensure_d_pos_cap(size_t idx)
{
    if (idx < d_pos_cap) return;
    size_t new_cap = d_pos_cap? d_pos_cap * 2 : 64;
    if (new_cap <= idx) new_cap = idx + 1;
    bool *new_arr = (bool *)malloc(new_cap);
    memset(new_arr, 0, new_cap);
    if (d_pos_used) {
        memcpy(new_arr, d_pos_used, d_pos_cap);
        free(d_pos_used);
    }
    d_pos_used = new_arr;
    d_pos_cap  = new_cap;
}
static void ensure_d_neg_cap(size_t idx)
{
    if (idx < d_neg_cap) return;
    size_t new_cap = d_neg_cap? d_neg_cap * 2 : 64;
    if (new_cap <= idx) new_cap = idx + 1;
    bool *new_arr = (bool *)malloc(new_cap);
    memset(new_arr, 0, new_cap);
    if (d_neg_used) {
        memcpy(new_arr, d_neg_used, d_neg_cap);
        free(d_neg_used);
    }
    d_neg_used = new_arr;
    d_neg_cap  = new_cap;
}
static void ensure_seq_cap(size_t sz)
{
    if (sz <= seq_cap) return;
    size_t new_cap = seq_cap? seq_cap * 2 : 128;
    if (new_cap < sz) new_cap = sz;
    seq_t *new_arr = (seq_t *)malloc(new_cap * sizeof(seq_t));
    if (seq_arr) {
        memcpy(new_arr, seq_arr, seq_len * sizeof(seq_t));
        free(seq_arr);
    }
    seq_arr = new_arr;
    seq_cap = new_cap;
}

/*-- main function ------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined for n=0, but harmless */

    /* initialise static state on first call */
    if (!computed_n) {
        /* first term: a(1)=0, d(1)=0 */
        computed_n = 1;
        a_used       = NULL; a_used_cap     = 0;
        d_pos_used   = NULL; d_pos_cap      = 0;
        d_neg_used   = NULL; d_neg_cap      = 0;
        seq_arr      = NULL; seq_cap        = 0;

        ensure_a_cap(0);
        a_used[0] = true;
        ensure_d_pos_cap(0);
        d_pos_used[0] = true;
        ensure_seq_cap(1);
        seq_arr[0] = 0;
        seq_len   = 1;
    }

    /* generate further terms if required */
    while (computed_n < n) {
        seq_t a_k = seq_arr[computed_n - 1];

        /* Step 1 – try negative increments */
        long long start = (long long)1 - (long long)a_k + 1; /* first integer > 1‑a_k */
        long long chosen_h = 0;
        bool found = false;
        for (long long h = start; h < 0; h++) {
            if (h < 0) {
                size_t idx_neg = (size_t)(-h);   /* negative index */
                if (idx_neg < d_neg_cap && d_neg_used[idx_neg]) continue;
                size_t a_v = (size_t)(a_k + (seq_t)h);
                ensure_a_cap(a_v);
                if (a_v < a_used_cap && a_used[a_v]) continue;
                chosen_h = h;
                found = true;
                break;
            }
        }

        /* Step 2 – positive increment if no negative step works */
        long long h;
        if (!found) {
            for (h = 1; ; h++) {
                size_t h_u = (size_t)h;
                if (h_u < d_pos_cap && d_pos_used[h_u]) continue;

                long long idx = (long long)a_k - h;
                bool a_present = false;
                if (idx >= 0 && (size_t)idx < a_used_cap && a_used[(size_t)idx]) {
                    a_present = true;
                }
                if (!a_present) {
                    chosen_h = h;
                    break;
                }
            }
        } else {
            h = chosen_h;
        }

        /* update d set */
        if (h >= 0) {
            ensure_d_pos_cap((size_t)h);
            d_pos_used[(size_t)h] = true;
        } else {
            ensure_d_neg_cap((size_t)(-h));
            d_neg_used[(size_t)(-h)] = true;
        }

        /* update a set and sequence */
        seq_t a_next = a_k + (seq_t)h;
        size_t a_next_u = (size_t)a_next;
        ensure_a_cap(a_next_u);
        a_used[a_next_u] = true;

        ensure_seq_cap(computed_n + 1);
        seq_arr[computed_n] = a_next;
        computed_n++;
        seq_len++;
    }

    return seq_arr[n - 1];
}
